#include <bits/stdc++.h>
using namespace std;

int main() {
	int n;
	int a[50]={};
	cin>>n;
	for(int i=0;i<n;i++){
		cin>>a[i];
	}

	int ans=0;
	for(int i=0;i<n;i++){
		for(int j=0;j<=i;j++){
			int s=0;
			for(int k=j;k<=i;k++)s+=a[k];
			bool ok=true;
			for(int k=j;k<=i;k++)if(s%a[k]==0)ok=false;
			if(ok)ans++;
		}
	}
	cout<<ans<<endl;
	return 0;
}

n=int(input())
a=list(map(int, input().split()))
ans=0

for i in range(n):
    for j in range(i+1):
        s=0
        for k in range(j,i+1):
            s+=a[k]
        flag=True
        for k in range(j,i+1):
            if s%a[k]==0:
                flag=False
        if flag:
            ans+=1

print(ans)
